insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('fb01c9c4-644c-4938-8129-85a22949538a', 'dd188452-f875-4e6f-9439-01479cebab43', null, 'topic'::public.curated_course_node_type, 'Cost models and asymptotics', 'This module establishes cost models and asymptotics as the course''s first working framework. It supplies the language and representations needed before the path advances to arrays and dynamic arrays.', 0),
  ('e3f7ec59-3cab-4986-ae16-7d24d0bab74b', 'dd188452-f875-4e6f-9439-01479cebab43', 'fb01c9c4-644c-4938-8129-85a22949538a', 'subtopic'::public.curated_course_node_type, 'RAM model', 'RAM model gives cost models and asymptotics a reusable representation for organizing assumptions, variables, and relationships before analysis begins. It appears before big-o/theta/omega because that next topic assumes this starting point.', 0),
  ('8e09e15a-2d9c-4809-a74f-cb3538c8e916', 'dd188452-f875-4e6f-9439-01479cebab43', 'fb01c9c4-644c-4938-8129-85a22949538a', 'subtopic'::public.curated_course_node_type, 'Big-O/Theta/Omega', 'Big-O/Theta/Omega identifies a specific object, distinction, or relationship within cost models and asymptotics. Learners need to recognize and use it before combining this module''s ideas in later work. After ram model, big-o/theta/omega supplies what is needed to address empirical timing.', 1),
  ('3524917d-655c-4f9d-b55c-c8720d57e00d', 'dd188452-f875-4e6f-9439-01479cebab43', 'fb01c9c4-644c-4938-8129-85a22949538a', 'subtopic'::public.curated_course_node_type, 'Empirical timing', 'Empirical timing identifies a specific object, distinction, or relationship within cost models and asymptotics. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, empirical timing carries the completed idea into arrays and dynamic arrays.', 2),
  ('7c6adbc6-524c-4638-99a3-25fa738fbbb2', 'dd188452-f875-4e6f-9439-01479cebab43', null, 'topic'::public.curated_course_node_type, 'Arrays and dynamic arrays', 'This module builds directly on cost models and asymptotics and develops arrays and dynamic arrays. It belongs here because its methods and distinctions are prerequisites for linked structures.', 1),
  ('498f505d-24d6-442e-bfad-89b9fd81c091', 'dd188452-f875-4e6f-9439-01479cebab43', '7c6adbc6-524c-4638-99a3-25fa738fbbb2', 'subtopic'::public.curated_course_node_type, 'Indexing', 'Indexing is an executable part of arrays and dynamic arrays; its correctness, cost, and failure modes recur in later problems and implementations. It appears before resizing because that next topic assumes this starting point.', 0),
  ('8c22abd7-7b22-48b9-84e6-a24ba574e531', 'dd188452-f875-4e6f-9439-01479cebab43', '7c6adbc6-524c-4638-99a3-25fa738fbbb2', 'subtopic'::public.curated_course_node_type, 'Resizing', 'Resizing identifies a specific object, distinction, or relationship within arrays and dynamic arrays. Learners need to recognize and use it before combining this module''s ideas in later work. After indexing, resizing supplies what is needed to address amortized analysis.', 1),
  ('c40af31a-4c25-4d26-9c1d-641d0d288289', 'dd188452-f875-4e6f-9439-01479cebab43', '7c6adbc6-524c-4638-99a3-25fa738fbbb2', 'subtopic'::public.curated_course_node_type, 'Amortized analysis', 'Amortized analysis identifies a specific object, distinction, or relationship within arrays and dynamic arrays. Learners need to recognize and use it before combining this module''s ideas in later work. After resizing, amortized analysis supplies what is needed to address locality.', 2),
  ('ed0ea279-c755-4497-9a37-b760eadf8a8f', 'dd188452-f875-4e6f-9439-01479cebab43', '7c6adbc6-524c-4638-99a3-25fa738fbbb2', 'subtopic'::public.curated_course_node_type, 'Locality', 'Locality identifies a specific object, distinction, or relationship within arrays and dynamic arrays. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, locality carries the completed idea into linked structures.', 3),
  ('b9875492-312e-4665-941a-a17192a07c61', 'dd188452-f875-4e6f-9439-01479cebab43', null, 'topic'::public.curated_course_node_type, 'Linked structures', 'This module builds directly on arrays and dynamic arrays and develops linked structures. It belongs here because its methods and distinctions are prerequisites for stacks, queues, and deques.', 2),
  ('eab6163c-5a4c-4d97-9970-312cff347ba7', 'dd188452-f875-4e6f-9439-01479cebab43', 'b9875492-312e-4665-941a-a17192a07c61', 'subtopic'::public.curated_course_node_type, 'Singly/doubly linked lists', 'Singly/doubly linked lists identifies a specific object, distinction, or relationship within linked structures. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before sentinels because that next topic assumes this starting point.', 0),
  ('9546103e-90b7-47f8-9a01-3d1508a29984', 'dd188452-f875-4e6f-9439-01479cebab43', 'b9875492-312e-4665-941a-a17192a07c61', 'subtopic'::public.curated_course_node_type, 'Sentinels', 'Sentinels identifies a specific object, distinction, or relationship within linked structures. Learners need to recognize and use it before combining this module''s ideas in later work. After singly/doubly linked lists, sentinels supplies what is needed to address iterators.', 1),
  ('cae586b6-3f15-41b0-a772-1b922fe5c114', 'dd188452-f875-4e6f-9439-01479cebab43', 'b9875492-312e-4665-941a-a17192a07c61', 'subtopic'::public.curated_course_node_type, 'Iterators', 'Iterators identifies a specific object, distinction, or relationship within linked structures. Learners need to recognize and use it before combining this module''s ideas in later work. After sentinels, iterators supplies what is needed to address ownership.', 2),
  ('cd48b5a2-deb9-4113-88f7-206665dfc2b5', 'dd188452-f875-4e6f-9439-01479cebab43', 'b9875492-312e-4665-941a-a17192a07c61', 'subtopic'::public.curated_course_node_type, 'Ownership', 'Ownership identifies a specific object, distinction, or relationship within linked structures. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, ownership carries the completed idea into stacks, queues, and deques.', 3),
  ('a2d55f99-8e43-4468-88d4-d7f7bd435776', 'dd188452-f875-4e6f-9439-01479cebab43', null, 'topic'::public.curated_course_node_type, 'Stacks, queues, and deques', 'This module builds directly on linked structures and develops stacks, queues, and deques. It belongs here because its methods and distinctions are prerequisites for recursion and divide-and-conquer.', 3),
  ('3d28a3ca-7cd4-4c2e-8b48-e14d7567b9a2', 'dd188452-f875-4e6f-9439-01479cebab43', 'a2d55f99-8e43-4468-88d4-d7f7bd435776', 'subtopic'::public.curated_course_node_type, 'Interfaces', 'Interfaces identifies a specific object, distinction, or relationship within stacks, queues, and deques. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before implementations because that next topic assumes this starting point.', 0),
  ('3ded2c2b-5061-4716-9555-eb6d166042b0', 'dd188452-f875-4e6f-9439-01479cebab43', 'a2d55f99-8e43-4468-88d4-d7f7bd435776', 'subtopic'::public.curated_course_node_type, 'Implementations', 'Implementations turns the theory of stacks, queues, and deques into a defensible decision and exposes the relevant structure, cost, or performance trade-offs. After interfaces, implementations supplies what is needed to address application patterns.', 1),
  ('0762820f-13b1-4eea-a37b-1f683cfda3d9', 'dd188452-f875-4e6f-9439-01479cebab43', 'a2d55f99-8e43-4468-88d4-d7f7bd435776', 'subtopic'::public.curated_course_node_type, 'Application patterns', 'Application patterns identifies a specific object, distinction, or relationship within stacks, queues, and deques. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, application patterns carries the completed idea into recursion and divide-and-conquer.', 2),
  ('1fca231a-b8a4-41aa-9bd0-c95cca5a9c90', 'dd188452-f875-4e6f-9439-01479cebab43', null, 'topic'::public.curated_course_node_type, 'Recursion and divide-and-conquer', 'This module builds directly on stacks, queues, and deques and develops recursion and divide-and-conquer. It belongs here because its methods and distinctions are prerequisites for hash tables.', 4),
  ('73070eaf-6baf-4d82-8938-9b7d3de3ffa0', 'dd188452-f875-4e6f-9439-01479cebab43', '1fca231a-b8a4-41aa-9bd0-c95cca5a9c90', 'subtopic'::public.curated_course_node_type, 'Call stacks', 'Call stacks identifies a specific object, distinction, or relationship within recursion and divide-and-conquer. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before recurrences because that next topic assumes this starting point.', 0),
  ('18df721b-4df4-4226-b1dd-d1209235ed88', 'dd188452-f875-4e6f-9439-01479cebab43', '1fca231a-b8a4-41aa-9bd0-c95cca5a9c90', 'subtopic'::public.curated_course_node_type, 'Recurrences', 'Recurrences identifies a specific object, distinction, or relationship within recursion and divide-and-conquer. Learners need to recognize and use it before combining this module''s ideas in later work. After call stacks, recurrences supplies what is needed to address merge sort.', 1),
  ('d34e79cc-c00e-4836-bf17-233991e99909', 'dd188452-f875-4e6f-9439-01479cebab43', '1fca231a-b8a4-41aa-9bd0-c95cca5a9c90', 'subtopic'::public.curated_course_node_type, 'Merge sort', 'Merge sort identifies a specific object, distinction, or relationship within recursion and divide-and-conquer. Learners need to recognize and use it before combining this module''s ideas in later work. After recurrences, merge sort supplies what is needed to address binary search.', 2),
  ('e593ef24-5acd-4dc4-ad97-771445991059', 'dd188452-f875-4e6f-9439-01479cebab43', '1fca231a-b8a4-41aa-9bd0-c95cca5a9c90', 'subtopic'::public.curated_course_node_type, 'Binary search', 'Binary search is an executable part of recursion and divide-and-conquer; its correctness, cost, and failure modes recur in later problems and implementations. As the final topic in this module, binary search carries the completed idea into hash tables.', 3),
  ('ee391d39-becf-4511-b9fe-d748b74c2409', 'dd188452-f875-4e6f-9439-01479cebab43', null, 'topic'::public.curated_course_node_type, 'Hash tables', 'This module builds directly on recursion and divide-and-conquer and develops hash tables. It belongs here because its methods and distinctions are prerequisites for trees.', 5),
  ('6f08a4c2-49d8-4342-adcf-5989af513f15', 'dd188452-f875-4e6f-9439-01479cebab43', 'ee391d39-becf-4511-b9fe-d748b74c2409', 'subtopic'::public.curated_course_node_type, 'Hash functions', 'Hash functions identifies a specific object, distinction, or relationship within hash tables. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before collision resolution because that next topic assumes this starting point.', 0),
  ('f2c92832-ea81-4779-b100-5dcd3d81d671', 'dd188452-f875-4e6f-9439-01479cebab43', 'ee391d39-becf-4511-b9fe-d748b74c2409', 'subtopic'::public.curated_course_node_type, 'Collision resolution', 'Collision resolution identifies a specific object, distinction, or relationship within hash tables. Learners need to recognize and use it before combining this module''s ideas in later work. After hash functions, collision resolution supplies what is needed to address load factor.', 1),
  ('538c41fe-52bb-46da-9384-5c967e831626', 'dd188452-f875-4e6f-9439-01479cebab43', 'ee391d39-becf-4511-b9fe-d748b74c2409', 'subtopic'::public.curated_course_node_type, 'Load factor', 'Load factor identifies a specific object, distinction, or relationship within hash tables. Learners need to recognize and use it before combining this module''s ideas in later work. After collision resolution, load factor supplies what is needed to address expected analysis.', 2),
  ('568eadea-9b7e-4d03-8367-324f1441d559', 'dd188452-f875-4e6f-9439-01479cebab43', 'ee391d39-becf-4511-b9fe-d748b74c2409', 'subtopic'::public.curated_course_node_type, 'Expected analysis', 'Expected analysis identifies a specific object, distinction, or relationship within hash tables. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, expected analysis carries the completed idea into trees.', 3),
  ('6197cf7e-d2b4-4041-9b51-8c85471511b1', 'dd188452-f875-4e6f-9439-01479cebab43', null, 'topic'::public.curated_course_node_type, 'Trees', 'This module builds directly on hash tables and develops trees. It belongs here because its methods and distinctions are prerequisites for balanced search trees.', 6),
  ('2babf25f-3f82-4165-acb6-323bfe9665b3', 'dd188452-f875-4e6f-9439-01479cebab43', '6197cf7e-d2b4-4041-9b51-8c85471511b1', 'subtopic'::public.curated_course_node_type, 'Traversals', 'Traversals identifies a specific object, distinction, or relationship within trees. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before bst operations because that next topic assumes this starting point.', 0),
  ('d3bbf0b5-d873-4ccf-a024-8c122f8ddc40', 'dd188452-f875-4e6f-9439-01479cebab43', '6197cf7e-d2b4-4041-9b51-8c85471511b1', 'subtopic'::public.curated_course_node_type, 'BST operations', 'BST operations identifies a specific object, distinction, or relationship within trees. Learners need to recognize and use it before combining this module''s ideas in later work. After traversals, bst operations supplies what is needed to address invariants.', 1),
  ('d19e452a-8c50-48b5-9226-0d0561d2c810', 'dd188452-f875-4e6f-9439-01479cebab43', '6197cf7e-d2b4-4041-9b51-8c85471511b1', 'subtopic'::public.curated_course_node_type, 'Invariants', 'Invariants identifies a specific object, distinction, or relationship within trees. Learners need to recognize and use it before combining this module''s ideas in later work. After bst operations, invariants supplies what is needed to address order statistics.', 2),
  ('53d3c10a-cd94-4ea3-b007-7af25762bb7b', 'dd188452-f875-4e6f-9439-01479cebab43', '6197cf7e-d2b4-4041-9b51-8c85471511b1', 'subtopic'::public.curated_course_node_type, 'Order statistics', 'Order statistics identifies a specific object, distinction, or relationship within trees. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, order statistics carries the completed idea into balanced search trees.', 3),
  ('bb76c739-1fad-4615-ad9a-7e26582c8cd4', 'dd188452-f875-4e6f-9439-01479cebab43', null, 'topic'::public.curated_course_node_type, 'Balanced search trees', 'This module builds directly on trees and develops balanced search trees. It belongs here because its methods and distinctions are prerequisites for heaps and priority queues.', 7),
  ('6c138b8d-9ef4-4459-8d30-5b2bfacd5440', 'dd188452-f875-4e6f-9439-01479cebab43', 'bb76c739-1fad-4615-ad9a-7e26582c8cd4', 'subtopic'::public.curated_course_node_type, 'AVL/red-black concepts', 'AVL/red-black concepts identifies a specific object, distinction, or relationship within balanced search trees. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before rotations because that next topic assumes this starting point.', 0),
  ('5809b8ce-d35a-4d8f-8e81-ed6076076d4b', 'dd188452-f875-4e6f-9439-01479cebab43', 'bb76c739-1fad-4615-ad9a-7e26582c8cd4', 'subtopic'::public.curated_course_node_type, 'Rotations', 'Rotations identifies a specific object, distinction, or relationship within balanced search trees. Learners need to recognize and use it before combining this module''s ideas in later work. After avl/red-black concepts, rotations supplies what is needed to address logarithmic guarantees.', 1),
  ('5f5012c6-aa6e-4061-a476-a3fc64501031', 'dd188452-f875-4e6f-9439-01479cebab43', 'bb76c739-1fad-4615-ad9a-7e26582c8cd4', 'subtopic'::public.curated_course_node_type, 'Logarithmic guarantees', 'Logarithmic guarantees identifies a specific object, distinction, or relationship within balanced search trees. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, logarithmic guarantees carries the completed idea into heaps and priority queues.', 2),
  ('de87992e-a5d4-4a53-81f4-21d8e1c60d10', 'dd188452-f875-4e6f-9439-01479cebab43', null, 'topic'::public.curated_course_node_type, 'Heaps and priority queues', 'This module builds directly on balanced search trees and develops heaps and priority queues. It belongs here because its methods and distinctions are prerequisites for graphs.', 8),
  ('ce81ae52-6b2d-4168-ae0b-354673f78309', 'dd188452-f875-4e6f-9439-01479cebab43', 'de87992e-a5d4-4a53-81f4-21d8e1c60d10', 'subtopic'::public.curated_course_node_type, 'Heapify', 'Heapify identifies a specific object, distinction, or relationship within heaps and priority queues. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before heapsort because that next topic assumes this starting point.', 0),
  ('79eb1c12-98c8-4740-be8c-da57f6065aed', 'dd188452-f875-4e6f-9439-01479cebab43', 'de87992e-a5d4-4a53-81f4-21d8e1c60d10', 'subtopic'::public.curated_course_node_type, 'Heapsort', 'Heapsort identifies a specific object, distinction, or relationship within heaps and priority queues. Learners need to recognize and use it before combining this module''s ideas in later work. After heapify, heapsort supplies what is needed to address indexed queues.', 1);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('856b63ba-81d4-468e-afaa-86f2f0febb01', 'dd188452-f875-4e6f-9439-01479cebab43', 'de87992e-a5d4-4a53-81f4-21d8e1c60d10', 'subtopic'::public.curated_course_node_type, 'Indexed queues', 'Indexed queues is an executable part of heaps and priority queues; its correctness, cost, and failure modes recur in later problems and implementations. After heapsort, indexed queues supplies what is needed to address scheduling.', 2),
  ('969f497a-a371-4396-b8d5-f85ad311d12c', 'dd188452-f875-4e6f-9439-01479cebab43', 'de87992e-a5d4-4a53-81f4-21d8e1c60d10', 'subtopic'::public.curated_course_node_type, 'Scheduling', 'Scheduling identifies a specific object, distinction, or relationship within heaps and priority queues. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, scheduling carries the completed idea into graphs.', 3),
  ('faebb6f6-be14-469c-b3a0-15b879c1cc0d', 'dd188452-f875-4e6f-9439-01479cebab43', null, 'topic'::public.curated_course_node_type, 'Graphs', 'This module builds directly on heaps and priority queues and develops graphs. It belongs here because its methods and distinctions are prerequisites for union–find and graph optimization.', 9),
  ('1d866426-9d86-4a76-b381-091c849b4970', 'dd188452-f875-4e6f-9439-01479cebab43', 'faebb6f6-be14-469c-b3a0-15b879c1cc0d', 'subtopic'::public.curated_course_node_type, 'Representations', 'Representations gives graphs a reusable representation for organizing assumptions, variables, and relationships before analysis begins. It appears before bfs/dfs because that next topic assumes this starting point.', 0),
  ('a360dafd-914b-4be0-a21e-2975c8e37e7a', 'dd188452-f875-4e6f-9439-01479cebab43', 'faebb6f6-be14-469c-b3a0-15b879c1cc0d', 'subtopic'::public.curated_course_node_type, 'BFS/DFS', 'BFS/DFS identifies a specific object, distinction, or relationship within graphs. Learners need to recognize and use it before combining this module''s ideas in later work. After representations, bfs/dfs supplies what is needed to address connectivity.', 1),
  ('a6fd413f-bd0b-47ef-98fa-9c038433dd9b', 'dd188452-f875-4e6f-9439-01479cebab43', 'faebb6f6-be14-469c-b3a0-15b879c1cc0d', 'subtopic'::public.curated_course_node_type, 'Connectivity', 'Connectivity identifies a specific object, distinction, or relationship within graphs. Learners need to recognize and use it before combining this module''s ideas in later work. After bfs/dfs, connectivity supplies what is needed to address topological order.', 2),
  ('f41008a9-074d-462a-a64a-f6f6184b073f', 'dd188452-f875-4e6f-9439-01479cebab43', 'faebb6f6-be14-469c-b3a0-15b879c1cc0d', 'subtopic'::public.curated_course_node_type, 'Topological order', 'Topological order provides a formal guarantee or inference rule for graphs, allowing later conclusions to be justified rather than inferred from examples alone. As the final topic in this module, topological order carries the completed idea into union–find and graph optimization.', 3),
  ('7bdf41b1-049e-4ee5-bc5e-a38c74b007ab', 'dd188452-f875-4e6f-9439-01479cebab43', null, 'topic'::public.curated_course_node_type, 'Union–find and graph optimization', 'This module builds directly on graphs and develops union–find and graph optimization. It belongs here because its methods and distinctions are prerequisites for advanced structures and selection.', 10),
  ('c1dc8af3-beb3-479a-80fd-d62223999cbf', 'dd188452-f875-4e6f-9439-01479cebab43', '7bdf41b1-049e-4ee5-bc5e-a38c74b007ab', 'subtopic'::public.curated_course_node_type, 'Path compression', 'Path compression identifies a specific object, distinction, or relationship within union–find and graph optimization. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before mst because that next topic assumes this starting point.', 0),
  ('daf348c3-89a9-48af-8ba1-e2e9a279c798', 'dd188452-f875-4e6f-9439-01479cebab43', '7bdf41b1-049e-4ee5-bc5e-a38c74b007ab', 'subtopic'::public.curated_course_node_type, 'MST', 'MST identifies a specific object, distinction, or relationship within union–find and graph optimization. Learners need to recognize and use it before combining this module''s ideas in later work. After path compression, mst supplies what is needed to address shortest-path overview.', 1),
  ('45ca6297-a8de-4099-9c74-4e16a79f7421', 'dd188452-f875-4e6f-9439-01479cebab43', '7bdf41b1-049e-4ee5-bc5e-a38c74b007ab', 'subtopic'::public.curated_course_node_type, 'Shortest-path overview', 'Shortest-path overview identifies a specific object, distinction, or relationship within union–find and graph optimization. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, shortest-path overview carries the completed idea into advanced structures and selection.', 2),
  ('93c4f21b-966a-448e-8fd2-4455a95fb0bf', 'dd188452-f875-4e6f-9439-01479cebab43', null, 'topic'::public.curated_course_node_type, 'Advanced structures and selection', 'This culminating module draws on union–find and graph optimization and develops advanced structures and selection. It belongs last because it requires the earlier tools to be selected, combined, and evaluated rather than used one at a time.', 11),
  ('eac53f38-e406-41a7-8bc6-3f4d5344b960', 'dd188452-f875-4e6f-9439-01479cebab43', '93c4f21b-966a-448e-8fd2-4455a95fb0bf', 'subtopic'::public.curated_course_node_type, 'Tries', 'Tries identifies a specific object, distinction, or relationship within advanced structures and selection. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before bloom filters because that next topic assumes this starting point.', 0),
